import { NextResponse, type NextRequest } from 'next/server'
import { createServerClient } from '@supabase/ssr'

// Define protected routes that require authentication
const protectedRoutes = ["/dashboard", "/transactions", "/categories"];

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // Create a response object
  let response = NextResponse.next({
    request: {
      headers: request.headers,
    },
  });

  // Create a Supabase client using server-side auth
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        get(name: string) {
          return request.cookies.get(name)?.value;
        },
        set(name: string, value: string, options: { path: string; maxAge: number; domain?: string; sameSite?: string; secure?: boolean }) {
          response.cookies.set({
            name,
            value,
            ...options,
          });
        },
        remove(name: string, options: { path: string }) {
          response.cookies.set({
            name,
            value: '',
            ...options,
            maxAge: 0,
          });
        },
      },
    }
  );

  // Refresh the session - this is critical for token refreshing
  const { data: { session } } = await supabase.auth.getSession();

  // Redirect logic based on authentication status
  if (protectedRoutes.some(route => pathname.startsWith(route)) && !session) {
    // Redirect unauthenticated users to login page
    return NextResponse.redirect(new URL("/auth/login", request.url));
  }

  // If user is already logged in and tries to access login page, redirect to dashboard
  if (pathname === "/auth/login" && session) {
    return NextResponse.redirect(new URL("/dashboard", request.url));
  }

  // If accessing the root, redirect based on authentication status
  if (pathname === "/") {
    if (session) {
      return NextResponse.redirect(new URL("/dashboard", request.url));
    } else {
      return NextResponse.redirect(new URL("/auth/login", request.url));
    }
  }

  // Return the response with any updated cookies
  return response;
}

// Configure matcher for middleware - it will only run on specified paths
export const config = {
  matcher: [
    '/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)',
  ],
}; 